const errorData = $input.first().json;

const workflowName = errorData.workflow?.name || "Unbekannter Workflow";
const nodeName = errorData.execution?.lastNodeExecuted || "Unbekannter Node";
const errorMessage = errorData.execution?.error?.message || "Keine Fehlermeldung verfuegbar";
const timestamp = new Date().toLocaleString("de-DE", { timeZone: "Europe/Berlin" });
const executionUrl = errorData.execution?.url || "";

// Tenant ist aktuell immer 'default' (Single-Tenant), aber Feld ist
// schon vorbereitet fuer Multi-Tenant-Skalierung (siehe Doku)
const tenantId = "default";

const text = `⚠️ Fehler bei Tenant "${tenantId}"\n` +
  `Workflow: "${workflowName}"\n` +
  `Node: ${nodeName}\n` +
  `Fehler: ${errorMessage}\n` +
  `Zeit: ${timestamp}` +
  (executionUrl ? `\nDetails: ${executionUrl}` : "");

return [{ json: { text, tenantId } }];
